    resources = []
    for r in (observation.get("resources", []) or []):
        try:
            resources.append((int(r[0]), int(r[1])))
        except Exception:
            pass

    def cheb(a, b, c, d):
        dx = a - c
        if dx < 0:
            dx = -dx
        dy = b - d
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    if resources:
        best = None
        for rx, ry in resources:
            ds = cheb(sx, sy, rx, ry)
            do = cheb(ox, oy, rx, ry)
            lead = do - ds
            score = (lead, -ds, -(abs(rx - ox) + abs(ry - oy)), -((rx + ry) & 3), rx, ry)
            if best is None or score > best[0]:
                best = (score, (rx, ry))
        tx, ty = best[1]
    else:
        ti = int(observation.get("turn_index", 0) or 0)
        if ((sx + sy + ti) & 1) == 0:
            tx, ty = 0, 0
        else:
            tx, ty = w - 1, h - 1

    # Choose move that reduces distance to target, avoids obstacles, and doesn't step out of bounds.
    best_move = (0, 0)
    best_val = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or nx >= w or ny < 0 or ny >= h:
            continue
        if (nx, ny) in obstacles:
            continue
        ns = cheb(nx, ny, tx, ty)
        # slight preference for moves towards opponent distance (to reduce their steals) when tied
        no = cheb(nx, ny, ox, oy)
        val = (-ns, abs(ox - tx) + abs(oy - ty), -no, -((nx + ny) & 3))
        if best_val is None or val > best_val:
            best_val = val
            best_move = (dx, dy)
    return [int(best_move[0]), int(best_move[1])]

